def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        runs = []
        start = 0
        for i in range(1, len(row) + 1):
            if i == len(row) or row[i] != row[start]:
                runs.append((start, i, row[start]))
                start = i
        if len(runs) == 2:
            a, b = runs
            if a[2] != b[2]:
                for j in range(b[0], b[1]):
                    row[j] = 1
    return out
